-- Post-Flight Verification Queries
SELECT company, COUNT(*) as total_campaigns FROM campaigns GROUP BY company;
SELECT c.company, COUNT(v.id) as total_videos, COUNT(DISTINCT cc.creator_id) as total_creators FROM campaigns c LEFT JOIN campaign_creators cc ON c.id = cc.campaign_id LEFT JOIN videos v ON cc.id = v.campaign_creator_id GROUP BY c.company;
COMMIT;
